using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
using MultiFPS;
using MultiFPS.UI;
using MultiFPS.UI.HUD;
using MultiFPS.Gameplay;
using ROM.UI.Sprint01;
namespace ROM.EditorTools {
[InitializeOnLoad] public static class GameUIProbe {
const string Key="ROM.GameUIProbe",Folder="Documentation/game-ui";
static int step,emote;static double began,next;static List<string> report;static RiftHub hub;static CharacterInstance actor;
static GameUIProbe(){EditorApplication.playModeStateChanged+=Changed;}
public static void Gameplay(){SessionState.SetBool(Key+"SkipEmotes",true);Run();}
public static void Run(){Directory.CreateDirectory(Folder);SessionState.SetBool(Key,true);EditorSceneManager.OpenScene("Assets/ROM/Scenes/MainMenu.unity");EditorApplication.isPlaying=true;}
static void Changed(PlayModeStateChange state){if(!SessionState.GetBool(Key,false))return;if(state==PlayModeStateChange.EnteredPlayMode){step=emote=0;began=EditorApplication.timeSinceStartup;next=began+3;report=new List<string>();EditorApplication.update+=Tick;}if(state==PlayModeStateChange.EnteredEditMode){SessionState.SetBool(Key,false);EditorApplication.Exit(SessionState.GetInt(Key+"Result",1));}}
static void Tick(){try{
if(EditorApplication.timeSinceStartup-began>240)throw new Exception("UI test timeout step="+step);
if(EditorApplication.timeSinceStartup<next)return;
if(step==0){hub=UnityEngine.Object.FindFirstObjectByType<RiftHub>();if(!hub||!hub.Stage||!hub.Stage.Ready)return;if(hub.Catalog.Emotes.Length<6)throw new Exception("Emote catalog missing");ROM.UI.EditorTools.SprintUIProbe.Capture(hub,Folder+"/main-menu.png",1920,1080);step=SessionState.GetBool(Key+"SkipEmotes",false)?3:1;}
if(step==1){int skin=emote/hub.Catalog.Emotes.Length;int index=emote%hub.Catalog.Emotes.Length;if(skin>=5){hub.Stage.StopEmote();step=3;next=EditorApplication.timeSinceStartup+.4;return;}if(index==0)hub.Stage.Show(hub.Catalog.Characters[skin]);if(!hub.Stage.PlayEmote(hub.Catalog.Emotes[index]))throw new Exception("Emote failed to start");step=2;next=EditorApplication.timeSinceStartup+.45;return;}
if(step==2){var animator=hub.Stage.PreviewAnimator;var expected=hub.Catalog.Emotes[emote%hub.Catalog.Emotes.Length];if(!animator||!animator.isHuman||!animator.GetCurrentAnimatorClipInfo(0).Any(c=>c.clip==expected.Clip&&c.weight>.7f))throw new Exception("Wrong emote pose "+emote);if(animator.applyRootMotion)throw new Exception("Lobby root motion enabled");report.Add("EMOTE skin="+(emote/hub.Catalog.Emotes.Length)+" "+expected.Name);if(emote%hub.Catalog.Emotes.Length==0)ROM.UI.EditorTools.SprintUIProbe.Capture(hub,Folder+"/emote-"+(emote/hub.Catalog.Emotes.Length)+".png",1920,1080);emote++;step=1;next=EditorApplication.timeSinceStartup+.03;return;}
if(step==3){if(hub.Stage.CurrentEmoteName!=null||hub.Stage.PreviewAnimator.runtimeAnimatorController==hub.Catalog.EmoteController)throw new Exception("Emote stop failed");hub.Stage.ShowParty(hub.Catalog,hub.Social);hub.Navigate(HubPage.Settings);ROM.UI.EditorTools.SprintUIProbe.Capture(hub,Folder+"/menu-settings.png",1920,1080);hub.Navigate(HubPage.Home);hub.Creator.BotsToggle.isOn=false;int raid=hub.Creator.GamemodeSelectionDropdown.options.FindIndex(o=>o.text=="Raid");if(raid>=0)hub.Creator.GamemodeSelectionDropdown.value=raid;hub.Creator.HostGameButton.onClick.Invoke();step=4;next=EditorApplication.timeSinceStartup+3;return;}
if(step==4){actor=UnityEngine.Object.FindObjectsByType<CharacterInstance>(FindObjectsSortMode.None).FirstOrDefault(c=>c.isOwned);if(!actor)return;actor.Health.CurrentHealth=actor.Health.MaxHealth=30000;step=5;next=EditorApplication.timeSinceStartup+22;return;}
if(step==5){var ui=UnityEngine.Object.FindFirstObjectByType<UICharacter>();if(!ui)throw new Exception("HUD missing");var so=new SerializedObject(ui);var health=so.FindProperty("_healthText").objectReferenceValue as Text;var ammo=so.FindProperty("_ammo").objectReferenceValue as Text;if(!health||string.IsNullOrEmpty(health.text)||!ammo||string.IsNullOrEmpty(ammo.text))throw new Exception("HUD bindings missing");foreach(var slot in UnityEngine.Object.FindObjectsByType<HudInventoryElement>(FindObjectsSortMode.None)){var data=new SerializedObject(slot);var name=data.FindProperty("_itemName").objectReferenceValue as Text;if(!name||!name.isActiveAndEnabled)throw new Exception("Inventory name label not active");}report.Add("HUD health="+health.text+" ammo="+ammo.text);foreach(var horde in UnityEngine.Object.FindObjectsByType<ROM.Horde.HordeHUD>(FindObjectsSortMode.None)){var h=new SerializedObject(horde);var theme=h.FindProperty("_theme").objectReferenceValue as ROM.Horde.HordeHUDTheme;var wave=h.FindProperty("_waveNumber").objectReferenceValue as Text;report.Add("HORDE theme="+(theme?theme.name:"null")+" color="+(theme?theme.Accent.ToString():"null")+" wavefont="+(wave&&wave.font?wave.font.name:"null")+" canvas="+horde.GetComponent<Canvas>().renderMode);}CaptureGame(Folder+"/hud.png");UIPauseMenu._instance.ShowPauseMenu(true);step=6;next=EditorApplication.timeSinceStartup+.8;return;}
if(step==6){var adapter=UnityEngine.Object.FindFirstObjectByType<RiftPauseAdapter>();if(!adapter||!adapter.Hub.InGame||!ClientFrontend.Pause)throw new Exception("New pause not active");CaptureGame(Folder+"/pause-settings.png");adapter.Hub.ShowArsenal();step=7;next=EditorApplication.timeSinceStartup+.3;return;}
if(step==7){var adapter=UnityEngine.Object.FindFirstObjectByType<RiftPauseAdapter>();if(!adapter.Hub.ArsenalPanel.gameObject.activeInHierarchy)throw new Exception("Arsenal unavailable");CaptureGame(Folder+"/pause-arsenal.png");adapter.ArsenalCancel.onClick.Invoke();adapter.Hub.ResumeRequested.Invoke();if(ClientFrontend.Pause)throw new Exception("Resume failed");report.Add("Pause / settings / arsenal / resume callbacks PASS");ChatUI.Instance.ShowChatInput(true);step=8;next=EditorApplication.timeSinceStartup+.3;return;}
if(step==8){if(!ChatUI.Instance.ChatWriting)throw new Exception("Chat input unavailable");CaptureGame(Folder+"/chat.png");ChatUI.Instance.ShowChatInput(false);var board=UnityEngine.Object.FindFirstObjectByType<ScoreBoard>();board.enabled=false;var so=new SerializedObject(board);((GameObject)so.FindProperty("_scoreBoard").objectReferenceValue).SetActive(true);board.StartCoroutine("RefreshScoreboard");step=9;next=EditorApplication.timeSinceStartup+.5;return;}
if(step==9){var enemies=GameManager.Players.Where(p=>p.BOT).Select(p=>p.PlayerInfo.Username).ToArray();foreach(var entry in UnityEngine.Object.FindObjectsByType<UIScoreBoardPlayerElement>(FindObjectsSortMode.None)){var data=new SerializedObject(entry);var name=data.FindProperty("_playerName").objectReferenceValue as Text;if(name&&enemies.Contains(name.text))throw new Exception("Enemy in squad scoreboard");}foreach(var row in UnityEngine.Object.FindObjectsByType<UIScoreBoardPlayerElement>(FindObjectsSortMode.None))if(Vector3.Distance(row.transform.localScale,Vector3.one)>.01f)throw new Exception("Scoreboard row scale invalid");CaptureGame(Folder+"/scoreboard.png");report.Add("Chat input and live scoreboard PASS");Finish(true);}
}catch(Exception e){Debug.LogException(e);report?.Add(e.ToString());Finish(false);}}
static void CaptureGame(string file){
var camera=GameplayCamera._instance?GameplayCamera._instance.GetComponent<Camera>():Camera.main;if(!camera)throw new Exception("No gameplay camera");
var visible=UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Where(c=>c.enabled&&c.isRootCanvas).ToArray();foreach(var c in visible)c.enabled=false;var rt=new RenderTexture(1920,1080,24);var original=camera.targetTexture;camera.targetTexture=rt;camera.Render();var world=Read(rt);camera.targetTexture=original;foreach(var c in visible)c.enabled=true;
var canvases=UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Where(c=>c.isRootCanvas&&c.renderMode==RenderMode.ScreenSpaceOverlay).ToArray();
var snapshots=canvases.Select(c=>(canvas:c,rect:(RectTransform)c.transform,position:c.transform.position,rotation:c.transform.rotation,scale:c.transform.localScale,size:((RectTransform)c.transform).sizeDelta,pivot:((RectTransform)c.transform).pivot,factor:c.scaleFactor,scaler:c.GetComponent<CanvasScaler>())).ToArray();
var layers=new Dictionary<GameObject,int>();
foreach(var snapshot in snapshots){var c=snapshot.canvas;Vector2 reference=snapshot.scaler?snapshot.scaler.referenceResolution:new Vector2(1920,1080);float factor=Mathf.Min(1920f/reference.x,1080f/reference.y);c.renderMode=RenderMode.WorldSpace;c.scaleFactor=1;if(snapshot.scaler)snapshot.scaler.enabled=false;snapshot.rect.pivot=new Vector2(.5f,.5f);snapshot.rect.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal,reference.x);snapshot.rect.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical,reference.y);snapshot.rect.position=Vector3.zero;snapshot.rect.rotation=Quaternion.identity;snapshot.rect.localScale=Vector3.one*factor;
foreach(var t in c.GetComponentsInChildren<Transform>(true)){if(!layers.ContainsKey(t.gameObject))layers.Add(t.gameObject,t.gameObject.layer);t.gameObject.layer=31;}
foreach(var view in c.GetComponentsInChildren<RiftHub>())view.SendMessage("Fit");}
var go=new GameObject("UI capture camera");var ui=go.AddComponent<Camera>();ui.orthographic=true;ui.orthographicSize=540;ui.transform.position=new Vector3(0,0,-1000);ui.farClipPlane=2000;ui.cullingMask=1<<31;ui.clearFlags=CameraClearFlags.SolidColor;ui.backgroundColor=Color.clear;ui.targetTexture=rt;foreach(var snapshot in snapshots)foreach(var text in snapshot.canvas.GetComponentsInChildren<Text>()){if(text.font)text.font.RequestCharactersInTexture(text.text,text.fontSize,text.fontStyle);text.SetAllDirty();}Canvas.ForceUpdateCanvases();ui.Render();var overlay=Read(rt);var foreground=overlay.GetPixels32();var pixels=world.GetPixels32();for(int i=0;i<pixels.Length;i++){float alpha=foreground[i].a/255f;pixels[i]=new Color32((byte)Mathf.Min(255,foreground[i].r+pixels[i].r*(1-alpha)),(byte)Mathf.Min(255,foreground[i].g+pixels[i].g*(1-alpha)),(byte)Mathf.Min(255,foreground[i].b+pixels[i].b*(1-alpha)),255);}world.SetPixels32(pixels);world.Apply();File.WriteAllBytes(file,world.EncodeToPNG());
foreach(var pair in layers)if(pair.Key)pair.Key.layer=pair.Value;
foreach(var snapshot in snapshots){snapshot.canvas.renderMode=RenderMode.ScreenSpaceOverlay;snapshot.canvas.scaleFactor=snapshot.factor;snapshot.rect.pivot=snapshot.pivot;snapshot.rect.position=snapshot.position;snapshot.rect.rotation=snapshot.rotation;snapshot.rect.localScale=snapshot.scale;snapshot.rect.sizeDelta=snapshot.size;if(snapshot.scaler)snapshot.scaler.enabled=true;foreach(var view in snapshot.canvas.GetComponentsInChildren<RiftHub>())view.SendMessage("Fit");}
ui.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(world);UnityEngine.Object.DestroyImmediate(overlay);
}
static Texture2D Read(RenderTexture rt){var previous=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);tex.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);tex.Apply();RenderTexture.active=previous;return tex;}
static void Finish(bool ok){EditorApplication.update-=Tick;File.WriteAllLines(Folder+"/validation.txt",new[]{ok?"PASS":"FAIL"}.Concat(report??new List<string>()));SessionState.SetInt(Key+"Result",ok?0:1);EditorApplication.isPlaying=false;}
}}
